<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder\SmtpOutboundConfigLoginAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigLoginAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SmtpOutboundConfigLoginAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getLogin returns null on a freshly created holder.
     */
    public function testLoginNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigLoginAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isLoginAssigned());
        $this->assertNull($holder->getLogin());
    }
}
class ImplWithSmtpOutboundConfigLoginAttributeHolderUnitTest
{
    use SmtpOutboundConfigLoginAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedLoginRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultLogin();
    }
}
